#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up grading on every pull request: each exercise repository gets the notify-leaderboard workflow
# (grader/exercise-repo/notify-leaderboard.yml) and a LEADERBOARD_TOKEN secret, so a pull request there
# starts "Grade submissions" here within a minute. Run it from the leaderboard repository:
#   grader/setup-pr-trigger.sh
# Run it again after adding a lesson; repositories already set up are skipped unless you choose otherwise.

HOOK_TEMPLATE="grader/exercise-repo/notify-leaderboard.yml"
HOOK_PATH=".github/workflows/notify-leaderboard.yml"

# The exercise repositories, from the lessons (grader/lessons.py reads lessons.json).
exercise_repos() {
  python3 -c 'import sys; sys.path.insert(0, "grader"); import lessons
print("\n".join(dict.fromkeys(l.repo for l in lessons.load("."))))'
}

# send_test_event: the event a pull request sends. Proves the token works; starts a grading run, which only
# grades commits not graded yet.
send_test_event() {
  GH_TOKEN=$LEADERBOARD_TOKEN gh api "repos/$LEADERBOARD_REPO/dispatches" \
    -f event_type=submission -f "client_payload[pr]=setup-pr-trigger test" >/dev/null 2>&1
}

# urlencode TEXT, for GitHub's prefilled "new file" page.
urlencode() { python3 -c 'import sys, urllib.parse; print(urllib.parse.quote(sys.stdin.read(), safe=""))' <<< "$1"; }

has_hook() { gh api "repos/$1/contents/$HOOK_PATH" >/dev/null 2>&1; }

setup_repo() {
  local repo="$1" admin branch hook
  stage "Exercise repository $repo"
  admin=$(gh api "repos/$repo" --jq .permissions.admin 2>/dev/null || echo false)
  if [[ "$admin" != true ]]; then
    warn "You are not an admin of $repo, so you can't add its secret or workflow."
    SKIPPED+=("$repo: ask its owner to run grader/setup-pr-trigger.sh, or to add $HOOK_PATH and the LEADERBOARD_TOKEN secret")
    pause "Press Enter to go on to the next repository"
    return
  fi
  if has_hook "$repo" && ! confirm "$repo already has the workflow. Set its secret and workflow again?"; then
    return
  fi

  set_repo_secret "$repo"

  branch=$(gh api "repos/$repo" --jq .default_branch)
  hook=$(sed "s|__LEADERBOARD_REPO__|$LEADERBOARD_REPO|" "$HOOK_TEMPLATE")
  say "Now add the workflow file. GitHub's new-file page opens with the file already filled in."
  open_url "https://github.com/$repo/new/$branch?filename=$HOOK_PATH&value=$(urlencode "$hook")"
  step "Check that the file name is $HOOK_PATH and that it mentions $LEADERBOARD_REPO."
  step "Click 'Commit changes...', keep 'Commit directly to the $branch branch', and confirm."
  pause "Press Enter once it is committed"
  if has_hook "$repo"; then
    printf '  %s✓ found%s %s in %s\n' "$GREEN" "$RESET" "$HOOK_PATH" "$repo"
  else
    warn "Can't see $HOOK_PATH in $repo yet."
    SKIPPED+=("$repo: commit $HOOK_PATH (copy $HOOK_TEMPLATE, with __LEADERBOARD_REPO__ replaced by $LEADERBOARD_REPO)")
    pause
  fi
}

# set_repo_secret REPO sets LEADERBOARD_TOKEN on an exercise repository (set_secret only sets the current one).
set_repo_secret() {
  if printf '%s' "$LEADERBOARD_TOKEN" | gh secret set LEADERBOARD_TOKEN -R "$1" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("LEADERBOARD_TOKEN on $1")
    printf '  %s✓ set%s secret LEADERBOARD_TOKEN on %s\n' "$GREEN" "$RESET" "$1"
  else
    warn "Could not set the secret on $1."
    SKIPPED+=("$1: add the secret LEADERBOARD_TOKEN (Settings → Secrets and variables → Actions)")
  fi
}

run_wizard() {

[[ -f lessons.json && -f "$HOOK_TEMPLATE" ]] || { echo "Run this from the leaderboard repository's top folder."; exit 1; }
REPOS=()
while IFS= read -r r; do REPOS+=("$r"); done < <(exercise_repos)
(( ${#REPOS[@]} )) || { echo "lessons.json lists no exercise repositories."; exit 1; }
TOTAL_STAGES=$((2 + ${#REPOS[@]}))

banner "Grade every pull request as it happens"

stage "GitHub CLI"
say "This wizard uses the GitHub CLI (gh) to check access and set secrets."
if ! command -v gh >/dev/null 2>&1; then
  warn "gh is not installed. Install it from https://cli.github.com, then run this again."
  exit 1
fi
until gh auth status >/dev/null 2>&1; do
  step "Log in: in another terminal run  gh auth login  and follow its steps."
  pause "Press Enter once you are logged in"
done
if [[ -z ${LEADERBOARD_REPO:-} ]]; then  # setup-leaderboard.sh passes it on
  say "Which repository is the leaderboard? It receives the events. Usually the one that publishes the page."
  ask LEADERBOARD_REPO "Leaderboard repository (owner/name):"
fi
until gh api "repos/$LEADERBOARD_REPO" >/dev/null 2>&1; do
  warn "Can't see $LEADERBOARD_REPO. Check the spelling."
  ask LEADERBOARD_REPO "Leaderboard repository (owner/name):"
done

stage "A token that can start grading"
say "Each exercise repository needs a token that may start a workflow on $LEADERBOARD_REPO, and nothing else."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: leaderboard-pr-trigger. Expiration: after the workshop ends."
step "Resource owner: ${LEADERBOARD_REPO%%/*}."
step "Repository access: Only select repositories → $LEADERBOARD_REPO."
step "Permissions → Repository permissions → Contents: Read and write. Leave everything else as it is."
step "Click 'Generate token' and copy it."
warn "GitHub needs Contents: write to accept the event, so this token could also change files in"
warn "$LEADERBOARD_REPO. Anyone who can edit an exercise repository's workflows could use it. Give it the"
warn "shortest expiry that covers the workshop, and revoke it when the workshop ends."
note "The token is never saved on this computer; it goes straight into each repository's secrets."
ask_secret LEADERBOARD_TOKEN "Paste the token:"
say "Checking it by sending the event a pull request sends (this starts a grading run, which is harmless)..."
until send_test_event; do
  warn "GitHub refused the event. Check the repository and the Contents: Read and write permission."
  ask_secret LEADERBOARD_TOKEN "Paste the token:"
done
printf '  %s✓ the token starts grading on%s %s\n' "$GREEN" "$RESET" "$LEADERBOARD_REPO"
open_url "https://github.com/$LEADERBOARD_REPO/actions/workflows/grade.yml"
step "A Grade submissions run should appear within a minute, started by a pull request change."
pause

for repo in "${REPOS[@]}"; do setup_repo "$repo"; done

finish
}

run_wizard "$@"; exit
